 function trig(t,op,row){ // simula triggers
  if(t==='accessory_purchases'){var a=DB.accessories.find(x=>x.id===row.accessory_id);if(op==='ins'){a.custo_medio=a.estoque+row.quantidade>0?((a.custo_medio*a.estoque)+row.custo_unitario*row.quantidade)/(a.estoque+row.quantidade):row.custo_unitario;a.estoque+=row.quantidade}else a.estoque-=row.quantidade}
  if(t==='accessory_sales'){var a=DB.accessories.find(x=>x.id===row.accessory_id);if(op==='ins'){if(a.estoque<row.quantidade)throw {message:'Estoque insuficiente'};row.custo_unitario=a.custo_medio;a.estoque-=row.quantidade}else a.estoque+=row.quantidade}
 }
 function Q(t){this.t=t;this.f=[];this.op='sel';this.one=false}
 Q.prototype.select=function(){if(this.op==='sel')this.op='sel';this.ret=true;return this};
 Q.prototype.eq=function(k,v){this.f.push(r=>r[k]===v);return this};
 Q.prototype.gte=function(k,v){return this};Q.prototype.limit=function(){return this};
 Q.prototype.order=function(){return this};
 Q.prototype.insert=function(r){this.op='ins';this.row=r;return this};
 Q.prototype.update=function(r){this.op='upd';this.row=r;return this};
 Q.prototype.delete=function(){this.op='del';return this};
 Q.prototype.single=Q.prototype.maybeSingle=function(){this.one=true;return this};
 Q.prototype.then=function(ok,ko){var me=this,res;try{var tab=DB[me.t]=DB[me.t]||[];
  if(me.op==='ins'){var rows=[].concat(me.row).map(r=>Object.assign({id:id(),created_at:new Date().toISOString(),estoque:me.t==='accessories'?0:undefined,custo_medio:me.t==='accessories'?0:undefined},r));rows.forEach(r=>{trig(me.t,'ins',r);tab.push(r)});res={data:me.one?rows[0]:rows,error:null}}
  else if(me.op==='upd'){tab.filter(r=>me.f.every(f=>f(r))).forEach(r=>Object.assign(r,me.row));res={data:null,error:null}}
  else if(me.op==='del'){var del=tab.filter(r=>me.f.every(f=>f(r)));del.forEach(r=>trig(me.t,'del',r));DB[me.t]=tab.filter(r=>!del.includes(r));res={data:null,error:null}}
  else{var d=tab.filter(r=>me.f.every(f=>f(r)));res={data:me.one?(d[0]||null):d,error:null}}
 }catch(e){res={data:null,error:{message:e.message}}}return Promise.resolve(res).then(ok,ko)};
